/**
 * Stored payment-channel facts used by facilitator rent cleanup.
 *
 * Only stores what the channel account refetch does not provide:
 * `payTo` (distribution preimage), `tokenProgram`, abandon-policy
 * `firstSeenAt`, voucher `expiresAt`, and `network`. Payer/payee/mint/
 * openSlot/status are read live before acting.
 *
 * Written on deposit (pre-broadcast) and claim settle; deleted when the PDA is gone.
 */
interface UptoChannelRecord {
    channelId: string;
    /** Distribution recipient sealed at open (`requirements.payTo`). */
    payTo: string;
    tokenProgram: string;
    /** Wall-clock ms when the facilitator first stored this channel. */
    firstSeenAt: number;
    /** Client voucher expiry (Unix seconds). Never shrinks on later upserts. */
    expiresAt: number;
    network: Network;
}
/** Pluggable storage of channels the facilitator sponsors rent for. */
interface UptoChannelStorage {
    get(channelId: string): Promise<UptoChannelRecord | undefined>;
    /**
     * Every stored record, in any order. The rent cleanup manager sorts by
     * channel id before scanning, so implementations do not have to.
     */
    list(): Promise<UptoChannelRecord[]>;
    upsert(record: UptoChannelRecord): Promise<void>;
    delete(channelId: string): Promise<void>;
}
/**
 * In-memory {@link UptoChannelStorage}. Preserves `firstSeenAt` and the
 * maximum `expiresAt` across upserts of the same `channelId`.
 */
declare class InMemoryUptoChannelStorage implements UptoChannelStorage {
    private readonly channels;
    /**
     * Look up a single stored channel.
     *
     * @param channelId - Channel PDA
     * @returns Stored record, or undefined when absent
     */
    get(channelId: string): Promise<UptoChannelRecord | undefined>;
    /**
     * List every stored channel record.
     *
     * @returns All stored channel records
     */
    list(): Promise<UptoChannelRecord[]>;
    /**
     * Insert or replace a record. Keeps the earlier `firstSeenAt` and the
     * later `expiresAt` when the channel was already stored.
     *
     * @param record - Full channel storage record
     */
    upsert(record: UptoChannelRecord): Promise<void>;
    /**
     * Remove a channel from storage.
     *
     * @param channelId - Channel PDA to remove
     */
    delete(channelId: string): Promise<void>;
}

/**
 * Facilitator-side async rent cleanup for SVM `upto` channels.
 *
 * Driven entirely by verify-time {@link UptoChannelStorage}: each pass lists
 * stored channels, refetches live account status, then acts on whatever is
 * ready (abandon-close / distribute / reclaim). RPC is not used for discovery.
 *
 * Signs with the live channel `payee` / `rent_payer` (same key in this scheme)
 * from the facilitator's existing signer pool — no dedicated cleanup key.
 *
 * Policy note (spec §8): sealing abandoned Open channels before the server
 * settles freezes the watermark and refunds the unsettled remainder to the
 * client. Abandon timing uses `min(expiresAt + grace, firstSeenAt + max)` so
 * normal vouchers expire cleanly while misconfigured long timeouts are capped.
 */

/** Default grace after voucher expiry before abandon-closing an Open channel. */
declare const DEFAULT_ABANDON_GRACE_SECS = 120;
/** Default reclaim instructions per cleanup transaction. */
declare const DEFAULT_MAX_RECLAIMS_PER_TX = 8;
/**
 * Largest reclaim batch proven, by the Go SDK's
 * `TestReclaimBatchFitsInOneTransaction`, to serialize under Solana's
 * `PACKET_DATA_SIZE` (1232 bytes) with every channel PDA distinct and one
 * shared fee payer. `maxReclaimsPerTx` is clamped to this so a misconfigured
 * operator value can never build a reclaim transaction that fails to
 * serialize or gets rejected on broadcast.
 */
declare const MAX_SAFE_RECLAIMS_PER_TX = 16;
/** Default close/distribute transactions the storage scan may submit per call. */
declare const DEFAULT_MAX_TXS_PER_RUN = 20;
/** Default reclaim transactions each rent payer may submit per call. */
declare const DEFAULT_MAX_TXS_PER_SIGNER = 20;
